catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading) {
        return;
    }

    // Jab bhi newValue 2 ya 3 nahi hai (jaise 1, 4, ya empty ''), pickup_address clear karo
    if (newValue != '2' && newValue != '3') {
        g_form.setValue('pickup_address', '');
        g_form.addInfoMessage(`Transfer Type  is not "Hospital to home (after discharge)" or "Hospital to another hospital or centre" -> pickup_address cleared`);
        return;
    }

    var hos = g_form.getValue('hospital');
    if (hos) {
        g_form.getReference('hospital', function(hosRec) {
            if (hosRec && hosRec.name) {
                g_form.setValue('pickup_address', hosRec.name);
            } else {
                g_form.setValue('pickup_address', '');
                g_form.addInfoMessage('hospital name not found');
            }
        });
    } else {
        g_form.setValue('pickup_address', '');
        g_form.addInfoMessage('hospital name not found');
    }
}
